using UnityEngine;
using UnityEditor;

public class CreateNewIngredients
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();

        string basePath = "Assets/Herbal/";
        string recipesPath = "Assets/Herbal/Recipes/";

        // Helper to Create or Get Item
        InventoryItem CreateItem(string path, string itemName, string desc, InventoryItem.ItemType type)
        {
            var item = AssetDatabase.LoadAssetAtPath<InventoryItem>(path);
            if (item == null)
            {
                item = ScriptableObject.CreateInstance<InventoryItem>();
                item.itemName = itemName;
                item.description = desc;
                item.itemType = type;
                AssetDatabase.CreateAsset(item, path);
            }
            else
            {
                item.itemName = itemName;
                item.description = desc;
                item.itemType = type;
                EditorUtility.SetDirty(item);
            }
            return item;
        }

        // Helper to Create or Get PlantData
        PlantData CreatePlantData(string path, string plantName, InventoryItem seedItem, InventoryItem harvestItem)
        {
            var pd = AssetDatabase.LoadAssetAtPath<PlantData>(path);
            if (pd == null)
            {
                pd = ScriptableObject.CreateInstance<PlantData>();
                pd.plantName = plantName;
                pd.growthTimeSeconds = 30f; 
                pd.seedItem = seedItem;
                pd.harvestItem = harvestItem;
                pd.harvestAmount = 2;
                AssetDatabase.CreateAsset(pd, path);
            }
            else
            {
                pd.plantName = plantName;
                pd.seedItem = seedItem;
                pd.harvestItem = harvestItem;
                EditorUtility.SetDirty(pd);
            }
            return pd;
        }

        // 1. Ingredients
        var itemSerai = CreateItem(basePath + "Serai.asset", "Serai", "Batang serai harum untuk bumbu dan obat.", InventoryItem.ItemType.Herb);
        var itemMint = CreateItem(basePath + "Daun Mint.asset", "Daun Mint", "Daun mint segar yang memberikan sensasi dingin.", InventoryItem.ItemType.Herb);
        var itemMeniran = CreateItem(basePath + "Meniran.asset", "Meniran", "Tumbuhan liar yang sering dipakai untuk obat demam.", InventoryItem.ItemType.Herb);
        var itemGulaAren = CreateItem(basePath + "Gula Aren.asset", "Gula Aren", "Pemanis alami dari nira aren.", InventoryItem.ItemType.Misc);
        var itemMadu = CreateItem(basePath + "Madu.asset", "Madu", "Madu asli dari lebah hutan.", InventoryItem.ItemType.Misc);

        // 2. Seeds
        var seedSerai = CreateItem(basePath + "Bibit Serai.asset", "Bibit Serai", "Bisa ditanam di kebun untuk menghasilkan serai.", InventoryItem.ItemType.Seed);
        var seedMint = CreateItem(basePath + "Bibit Daun Mint.asset", "Bibit Daun Mint", "Bisa ditanam di kebun untuk menghasilkan daun mint.", InventoryItem.ItemType.Seed);
        var seedMeniran = CreateItem(basePath + "Bibit Meniran.asset", "Bibit Meniran", "Bisa ditanam di kebun untuk menghasilkan meniran.", InventoryItem.ItemType.Seed);

        // 3. Plant Data
        var pdSerai = CreatePlantData(basePath + "PlantData_Serai.asset", "Tanaman Serai", seedSerai, itemSerai);
        var pdMint = CreatePlantData(basePath + "PlantData_DaunMint.asset", "Tanaman Mint", seedMint, itemMint);
        var pdMeniran = CreatePlantData(basePath + "PlantData_Meniran.asset", "Tanaman Meniran", seedMeniran, itemMeniran);

        // 4. Existing Items
        var itemJahe = AssetDatabase.LoadAssetAtPath<InventoryItem>(basePath + "Jahe.asset");
        var itemKunyit = AssetDatabase.LoadAssetAtPath<InventoryItem>(basePath + "Kunyit.asset");
        var itemKencur = AssetDatabase.LoadAssetAtPath<InventoryItem>(basePath + "Kencur.asset");
        var itemTemulawak = AssetDatabase.LoadAssetAtPath<InventoryItem>(basePath + "Temulawak.asset");

        // 5. Recipes and Result Items
        CookingRecipe CreateRecipe(string name, string desc, int hp, params (InventoryItem item, int amount)[] ingredients)
        {
            string itemPath = basePath + name + ".asset";
            var rItem = CreateItem(itemPath, name, desc, InventoryItem.ItemType.Cooked);

            string recipePath = recipesPath + name + ".asset";
            var recipe = AssetDatabase.LoadAssetAtPath<CookingRecipe>(recipePath);
            if (recipe == null)
            {
                recipe = ScriptableObject.CreateInstance<CookingRecipe>();
                AssetDatabase.CreateAsset(recipe, recipePath);
            }

            recipe.recipeName = name;
            recipe.description = desc;
            recipe.hpRestore = hp;
            recipe.resultItem = rItem;

            recipe.ingredients = new CookingRecipe.Ingredient[ingredients.Length];
            for (int i = 0; i < ingredients.Length; i++)
            {
                recipe.ingredients[i] = new CookingRecipe.Ingredient();
                if (ingredients[i].item != null)
                {
                    recipe.ingredients[i].itemName = ingredients[i].item.itemName;
                    recipe.ingredients[i].itemIcon = ingredients[i].item.icon;
                }
                recipe.ingredients[i].amountRequired = ingredients[i].amount;
            }
            EditorUtility.SetDirty(recipe);
            return recipe;
        }

        CreateRecipe("Jamu Pegal Linu", "Cocok untuk meredakan nyeri sendi dan badan pegal.", 30, (itemJahe, 1), (itemKunyit, 1), (itemSerai, 1));
        CreateRecipe("Jamu Penyegar", "Menghilangkan pusing dan mengembalikan kesegaran.", 25, (itemJahe, 1), (itemMint, 1));
        CreateRecipe("Wedang Herbal", "Minuman hangat untuk mengusir masuk angin.", 20, (itemJahe, 1), (itemGulaAren, 1), (itemSerai, 1));
        CreateRecipe("Ramuan Penurun Panas", "Ramuan tradisional ampuh untuk meredakan demam.", 35, (itemMeniran, 2), (itemKunyit, 1));
        CreateRecipe("Jamu Stamina", "Meningkatkan stamina untuk mengatasi kelelahan.", 40, (itemTemulawak, 1), (itemMadu, 1));
        CreateRecipe("Ramuan Anti Mual", "Menghangatkan perut dan meredakan rasa mual.", 20, (itemJahe, 1), (itemMint, 1));
        CreateRecipe("Ramuan Pernapasan", "Melegakan napas sesak dan tenggorokan.", 25, (itemKencur, 1), (itemMadu, 1));
        CreateRecipe("Jamu Sehat Desa", "Jamu pamungkas untuk pemulihan kondisi tubuh secara umum.", 50, (itemTemulawak, 1), (itemKunyit, 1), (itemMadu, 1));

        AssetDatabase.SaveAssets();
        sb.AppendLine("[SUCCESS] ScriptableObjects untuk 8 Resep Baru dan Bahan berhasil dibuat!");
        return sb.ToString();
    }
}
